#include <stdio.h>

int main(void) {
    char *row[3] = {"{a}", NULL, "{b}"};

    for (int i = 0; i < 3; i++) {
        if (row[i] == NULL) {
            continue;
        }
        printf("%d: %s\n", i, row[i]);
    }

    return 0;
}
